import { useState, type FormEvent } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
} from '@jinx-ui/react';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('member');
  const [notify, setNotify] = useState(true);
  const [sentTo, setSentTo] = useState<string | null>(null);

  const isValid = EMAIL_RE.test(email.trim());
  const errorText = touched && !isValid ? 'Введите адрес вида name@company.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValid) {
      setTouched(true);
      return;
    }
    setSentTo(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'grid', gap: '16px', maxWidth: '420px', fontFamily: 'var(--jx-font-sans)' }}
    >
      {sentTo && (
        <JxAlert intent="success" title="Приглашение отправлено">
          <span style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
            <span>Мы пригласили {sentTo}.</span>
            <JxButton variant="ghost" size="sm" onClick={() => setSentTo(null)}>
              Закрыть
            </JxButton>
          </span>
        </JxAlert>
      )}

      <JxInputField
        label="Электронная почта"
        type="email"
        required
        placeholder="name@company.com"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        onBlur={() => setTouched(true)}
        helperText="Приглашение придёт на этот адрес"
        errorText={errorText}
      />

      <JxSelect
        label="Роль"
        options={[
          { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
          { value: 'member', label: 'Участник' },
          { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
        ]}
        value={role}
        onValueChange={setRole}
      />

      <JxSwitch
        label="Отправить уведомление"
        checked={notify}
        onChange={(event) => setNotify(event.target.checked)}
      />

      <JxButton type="submit" variant="primary" disabled={!isValid}>
        Отправить приглашение
      </JxButton>
    </form>
  );
}

